# ============================================================
#  CROISSANTE !  -  des croissants surgissent de l'ecran en grossissant
#  (taille finale 10 cm reels), l'un apres l'autre, l'un sur l'autre,
#  jusqu'a remplir tous les ecrans.
#  - bandeau en haut : "Vous avez ete croissante ! ..."
#  - petite croix en haut a droite de chaque ecran pour quitter
#  - si le Gestionnaire des taches est ouvert, les croissants passent en arriere-plan
#  - s'arrete tout seul apres -Minutes minutes (15 par defaut)
#  Usage : powershell -ExecutionPolicy Bypass -File croissant.ps1 [-Cm 15] [-Duration 0.6] [-Minutes 30] [-Message "..."]
# ============================================================
param(
    [double]$Cm       = 10,     # largeur finale d'un croissant en centimetres reels
    [double]$Duration = 1.6,    # duree d'apparition d'un croissant (secondes)
    [double]$Gap      = 0.35,   # pause entre deux croissants (secondes)
    [int]$Minutes     = 15,
    # le texte entre *etoiles* est mis en valeur
    [string]$Message  = "Vous avez été croissanté ! Pour quitter, *ramenez des croissants*."
)

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Xaml, System.Windows.Forms, System.Drawing

$code = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Interop;
using System.Windows.Media;
using System.Windows.Media.Effects;
using System.Windows.Media.Imaging;
using System.Windows.Shapes;

public static class Croissant
{
    [DllImport("user32.dll")] static extern bool SetProcessDPIAware();
    [DllImport("user32.dll")] static extern int GetWindowLong(IntPtr h, int i);
    [DllImport("user32.dll")] static extern int SetWindowLong(IntPtr h, int i, int v);
    [DllImport("user32.dll")] static extern bool SetWindowPos(IntPtr h, IntPtr after, int x, int y, int cx, int cy, uint flags);
    [StructLayout(LayoutKind.Sequential)] struct RECT { public int L, T, R, B; }
    [DllImport("user32.dll")] static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("gdi32.dll", CharSet = CharSet.Unicode)] static extern IntPtr CreateDC(string drv, string dev, string o, IntPtr init);
    [DllImport("gdi32.dll")] static extern int GetDeviceCaps(IntPtr hdc, int idx);
    [DllImport("gdi32.dll")] static extern bool DeleteDC(IntPtr hdc);

    const uint NOSIZE = 0x0001, NOMOVE = 0x0002, NOACTIVATE = 0x0010;
    static readonly IntPtr TOPMOST = new IntPtr(-1), BOTTOM = new IntPtr(1);

    class Scr
    {
        public System.Drawing.Rectangle B;
        public double Wd, Hd;                      // taille ecran en DIP
        public BitmapSource[] Bmps;
        public double BW, BH;                      // taille d'un croissant (bitmap) en DIP
        public Window O; public Canvas OC; public IntPtr OH;
        public Window A; public Image AI; public ScaleTransform AS; public RotateTransform AR; public IntPtr AH;
        public int APW, APH;
        public Window Ban, X; public IntPtr BanH, XH;
        public List<Point> Pos = new List<Point>();
        public int Next;
        public double StartT = -1, NextAt = 0.5, Rot, TX, TY;
        public int Var; public bool Flip, Done;
    }

    static List<Scr> scrs = new List<Scr>();
    static Random rnd = new Random();
    static Application app;
    static Stopwatch sw;
    static double dpi = 1, dur, gap, endT, lastFrame, lastTm = -10;
    static bool tmPaused;

    static double Clamp01(double v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }

    // ---------- croissant : photo detouree (PNG integre au script) ----------
    static byte[] srcPix; static int srcW, srcH;

    static void LoadPhoto(string b64)
    {
        byte[] data = Convert.FromBase64String(b64);
        BitmapDecoder dec = BitmapDecoder.Create(new System.IO.MemoryStream(data), BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
        FormatConvertedBitmap fc = new FormatConvertedBitmap(dec.Frames[0], PixelFormats.Pbgra32, null, 0);
        srcW = fc.PixelWidth; srcH = fc.PixelHeight;
        srcPix = new byte[srcW * srcH * 4];
        fc.CopyPixels(srcPix, srcW * 4, 0);
    }

    // une variante = la photo avec une cuisson un peu plus claire/foncee, a la bonne taille, avec ombre douce
    static BitmapSource RenderCroissant(double wDip, double tint, int seed, out double bw, out double bh)
    {
        byte[] p = new byte[srcPix.Length];
        double warm = 1 + (tint - 1) * 0.5;
        for (int i = 0; i < p.Length; i += 4)
        {
            p[i]     = (byte)Math.Min((int)srcPix[i + 3], (int)(srcPix[i] * tint));
            p[i + 1] = (byte)Math.Min((int)srcPix[i + 3], (int)(srcPix[i + 1] * tint));
            p[i + 2] = (byte)Math.Min((int)srcPix[i + 3], (int)(srcPix[i + 2] * warm));
            p[i + 3] = srcPix[i + 3];
        }
        BitmapSource src = BitmapSource.Create(srcW, srcH, 96, 96, PixelFormats.Pbgra32, null, p, srcW * 4);
        src.Freeze();

        double cw = wDip, ch = wDip * srcH / (double)srcW;
        double m = wDip * 0.09;
        bw = cw + 2 * m; bh = ch + 2 * m;

        DrawingVisual dv = new DrawingVisual();
        RenderOptions.SetBitmapScalingMode(dv, BitmapScalingMode.HighQuality);
        using (DrawingContext dc = dv.RenderOpen()) dc.DrawImage(src, new Rect(m, m, cw, ch));
        DropShadowEffect ds = new DropShadowEffect();
        ds.Color = Colors.Black; ds.Opacity = 0.5; ds.Direction = 290;
        ds.ShadowDepth = wDip * 0.025; ds.BlurRadius = wDip * 0.07;
        dv.Effect = ds;
        ContainerVisual host = new ContainerVisual();
        host.Children.Add(dv);
        RenderTargetBitmap rtb = new RenderTargetBitmap((int)Math.Ceiling(bw * dpi), (int)Math.Ceiling(bh * dpi), 96 * dpi, 96 * dpi, PixelFormats.Pbgra32);
        rtb.Render(host);
        rtb.Freeze();
        return rtb;
    }

    // ---------- fenetres ----------
    static Window NewWin(object content, bool clickThrough)
    {
        Window w = new Window();
        w.WindowStyle = WindowStyle.None; w.AllowsTransparency = true; w.Background = Brushes.Transparent;
        w.Topmost = true; w.ShowInTaskbar = false; w.ShowActivated = false; w.ResizeMode = ResizeMode.NoResize;
        w.WindowStartupLocation = WindowStartupLocation.Manual; w.Left = -30000; w.Top = -30000;
        w.Content = content;
        w.SourceInitialized += delegate
        {
            IntPtr h = new WindowInteropHelper(w).Handle;
            int ex = GetWindowLong(h, -20) | 0x80 | 0x08000000;     // TOOLWINDOW | NOACTIVATE
            if (clickThrough) ex |= 0x20;                           // TRANSPARENT
            SetWindowLong(h, -20, ex);
        };
        return w;
    }
    static IntPtr Hwnd(Window w) { return new WindowInteropHelper(w).Handle; }
    static int WinW(IntPtr h) { RECT r; GetWindowRect(h, out r); return r.R - r.L; }
    static int WinH(IntPtr h) { RECT r; GetWindowRect(h, out r); return r.B - r.T; }

    static void SetMsg(TextBlock tb, string m)
    {
        tb.Inlines.Clear();
        string[] parts = m.Split('*');
        for (int i = 0; i < parts.Length; i++)
        {
            System.Windows.Documents.Run rr = new System.Windows.Documents.Run(parts[i]);
            if (i % 2 == 1) { rr.Foreground = new SolidColorBrush(Color.FromRgb(255, 206, 60)); rr.FontWeight = FontWeights.Bold; }
            tb.Inlines.Add(rr);
        }
    }

    static void BuildScreen(System.Windows.Forms.Screen scr, double cm, string msg)
    {
        Scr S = new Scr();
        S.B = scr.Bounds;
        S.Wd = S.B.Width / dpi; S.Hd = S.B.Height / dpi;

        // pixels par cm reel de CET ecran (taille physique EDID), sinon 96 dpi
        double pxPerCm = 96 * dpi / 2.54;
        try
        {
            IntPtr dc = CreateDC("DISPLAY", scr.DeviceName, null, IntPtr.Zero);
            if (dc != IntPtr.Zero)
            {
                int mm = GetDeviceCaps(dc, 4);   // HORZSIZE
                DeleteDC(dc);
                if (mm >= 150 && mm <= 2500)
                {
                    double v = S.B.Width / (mm / 10.0);
                    if (v > 15 && v < 250) pxPerCm = v;
                }
            }
        }
        catch { }
        double wDip = cm * pxPerCm / dpi;

        S.Bmps = new BitmapSource[4];
        for (int i = 0; i < 4; i++)
            S.Bmps[i] = RenderCroissant(wDip, 0.92 + rnd.NextDouble() * 0.12, rnd.Next(), out S.BW, out S.BH);

        // positions : grille melangee qui couvre tout l'ecran
        double stepX = S.BW * 0.42, stepY = S.BH * 0.42;
        int cols = (int)Math.Ceiling(S.Wd / stepX), rows = (int)Math.Ceiling(S.Hd / stepY);
        for (int ry = 0; ry <= rows; ry++)
            for (int cx = 0; cx <= cols; cx++)
                S.Pos.Add(new Point(cx * stepX + (rnd.NextDouble() - 0.5) * stepX * 0.5,
                                    ry * stepY + (rnd.NextDouble() - 0.5) * stepY * 0.5));
        for (int i = S.Pos.Count - 1; i > 0; i--) { int j = rnd.Next(i + 1); Point tmp = S.Pos[i]; S.Pos[i] = S.Pos[j]; S.Pos[j] = tmp; }
        S.NextAt = 0.4 + rnd.NextDouble() * 0.3;

        // 1) calque plein ecran qui garde les croissants poses
        S.OC = new Canvas();
        S.OC.Width = S.Wd; S.OC.Height = S.Hd;
        S.O = NewWin(S.OC, false);
        S.O.Width = S.Wd; S.O.Height = S.Hd;
        S.O.Loaded += delegate
        {
            S.OH = Hwnd(S.O);
            SetWindowPos(S.OH, TOPMOST, S.B.X, S.B.Y, S.B.Width, S.B.Height, NOACTIVATE);
        };

        // 2) fenetre d'animation du croissant qui surgit
        Grid ag = new Grid();
        ag.Width = S.BW * 1.25; ag.Height = S.BH * 1.25;
        S.AI = new Image();
        S.AI.Width = S.BW; S.AI.Height = S.BH; S.AI.Stretch = Stretch.Fill;
        S.AI.HorizontalAlignment = HorizontalAlignment.Center; S.AI.VerticalAlignment = VerticalAlignment.Center;
        S.AI.RenderTransformOrigin = new Point(0.5, 0.5);
        S.AS = new ScaleTransform(0.01, 0.01); S.AR = new RotateTransform(0);
        TransformGroup atg = new TransformGroup(); atg.Children.Add(S.AS); atg.Children.Add(S.AR);
        S.AI.RenderTransform = atg;
        ag.Children.Add(S.AI);
        S.A = NewWin(ag, true);
        S.A.Width = ag.Width; S.A.Height = ag.Height;
        S.A.Loaded += delegate { S.AH = Hwnd(S.A); S.APW = WinW(S.AH); S.APH = WinH(S.AH); };

        // 3) bandeau en haut
        TextBlock tb = new TextBlock();
        tb.FontFamily = new FontFamily("Segoe UI"); tb.FontSize = 24; tb.FontWeight = FontWeights.SemiBold; tb.Foreground = Brushes.White;
        SetMsg(tb, msg);
        Border bd = new Border();
        bd.CornerRadius = new CornerRadius(18); bd.Padding = new Thickness(26, 10, 26, 12);
        bd.Background = new SolidColorBrush(Color.FromArgb(215, 60, 32, 12));
        bd.BorderBrush = new SolidColorBrush(Color.FromArgb(150, 255, 214, 140)); bd.BorderThickness = new Thickness(1.5);
        DropShadowEffect bds = new DropShadowEffect(); bds.BlurRadius = 16; bds.ShadowDepth = 3; bds.Opacity = 0.55;
        bd.Effect = bds; bd.Child = tb;
        Grid bg = new Grid(); bg.Margin = new Thickness(18); bg.Children.Add(bd); bg.IsHitTestVisible = false;
        S.Ban = NewWin(bg, true);
        S.Ban.SizeToContent = SizeToContent.WidthAndHeight;
        S.Ban.Loaded += delegate
        {
            S.BanH = Hwnd(S.Ban);
            SetWindowPos(S.BanH, TOPMOST, S.B.X + (S.B.Width - WinW(S.BanH)) / 2, S.B.Y, 0, 0, NOSIZE | NOACTIVATE);
        };

        // 4) petite croix en haut a droite
        Border xb = new Border();
        xb.Width = 38; xb.Height = 38; xb.CornerRadius = new CornerRadius(19);
        xb.Background = new SolidColorBrush(Color.FromArgb(220, 30, 30, 34));
        xb.BorderBrush = new SolidColorBrush(Color.FromArgb(170, 255, 255, 255)); xb.BorderThickness = new Thickness(1.5);
        xb.Cursor = Cursors.Hand;
        TextBlock xt = new TextBlock();
        xt.Text = "✕"; xt.FontFamily = new FontFamily("Segoe UI Symbol"); xt.FontSize = 18; xt.Foreground = Brushes.White;
        xt.HorizontalAlignment = HorizontalAlignment.Center; xt.VerticalAlignment = VerticalAlignment.Center;
        xb.Child = xt;
        xb.MouseEnter += delegate { xb.Background = new SolidColorBrush(Color.FromArgb(235, 200, 30, 36)); };
        xb.MouseLeave += delegate { xb.Background = new SolidColorBrush(Color.FromArgb(220, 30, 30, 34)); };
        xb.MouseLeftButtonUp += delegate { app.Shutdown(); };
        Grid xg = new Grid(); xg.Margin = new Thickness(4); xg.Children.Add(xb);
        S.X = NewWin(xg, false);
        S.X.SizeToContent = SizeToContent.WidthAndHeight;
        S.X.Loaded += delegate
        {
            S.XH = Hwnd(S.X);
            SetWindowPos(S.XH, TOPMOST, S.B.Right - WinW(S.XH) - 10, S.B.Y + 10, 0, 0, NOSIZE | NOACTIVATE);
        };

        scrs.Add(S);
        S.O.Show(); S.A.Show(); S.Ban.Show(); S.X.Show();
    }

    static double EaseOutBack(double p)
    {
        double c1 = 0.9, c3 = c1 + 1, q = p - 1;
        return 1 + c3 * q * q * q + c1 * q * q;
    }

    public static void Run(double cm, double duration, double pause, double minutes, string msg, string photo)
    {
        LoadPhoto(photo);
        try { SetProcessDPIAware(); } catch { }
        using (System.Drawing.Graphics gr = System.Drawing.Graphics.FromHwnd(IntPtr.Zero)) dpi = gr.DpiX / 96.0;
        dur = Math.Max(0.15, duration); gap = Math.Max(0, pause); endT = minutes * 60;

        app = new Application();
        app.ShutdownMode = ShutdownMode.OnExplicitShutdown;
        foreach (System.Windows.Forms.Screen scr in System.Windows.Forms.Screen.AllScreens) BuildScreen(scr, cm, msg);
        sw = Stopwatch.StartNew();
        CompositionTarget.Rendering += OnFrame;
        app.Run();
    }

    static void OnFrame(object s, EventArgs e)
    {
        double t = sw.Elapsed.TotalSeconds;
        if (t - lastFrame < 0.016) return;
        lastFrame = t;
        if (t > endT) { CompositionTarget.Rendering -= OnFrame; app.Shutdown(); return; }

        // Gestionnaire des taches ouvert => on passe tout en arriere-plan
        if (t - lastTm > 1)
        {
            lastTm = t;
            Process[] ps = Process.GetProcessesByName("Taskmgr");
            bool tm = ps.Length > 0;
            foreach (Process p in ps) p.Dispose();
            if (tm != tmPaused)
            {
                tmPaused = tm;
                foreach (Scr S in scrs)
                    foreach (IntPtr h in new IntPtr[] { S.OH, S.AH, S.BanH, S.XH })
                        if (h != IntPtr.Zero) SetWindowPos(h, tm ? BOTTOM : TOPMOST, 0, 0, 0, 0, NOMOVE | NOSIZE | NOACTIVATE);
            }
        }

        foreach (Scr S in scrs)
        {
            if (S.Done || S.AH == IntPtr.Zero || S.OH == IntPtr.Zero) continue;

            if (S.StartT < 0)
            {
                if (t < S.NextAt) continue;
                // nouveau croissant
                Point p = S.Pos[S.Next];
                S.Var = rnd.Next(S.Bmps.Length);
                S.Rot = (rnd.NextDouble() - 0.5) * 50;
                S.Flip = rnd.Next(2) == 0;
                S.AI.Source = S.Bmps[S.Var];
                S.AS.ScaleX = 0.01; S.AS.ScaleY = 0.01;
                S.AI.Opacity = 0;
                // il part du centre de l'ecran et va vers sa place
                S.TX = S.B.X + p.X * dpi; S.TY = S.B.Y + p.Y * dpi;
                int x = (int)(S.B.X + S.B.Width / 2.0 - S.APW / 2.0);
                int y = (int)(S.B.Y + S.B.Height / 2.0 - S.APH / 2.0);
                SetWindowPos(S.AH, tmPaused ? BOTTOM : TOPMOST, x, y, 0, 0, NOSIZE | NOACTIVATE);
                S.StartT = t;
            }

            double pr = (t - S.StartT) / dur;
            if (pr >= 1)
            {
                // on le pose sur le calque, par-dessus les precedents
                Point p = S.Pos[S.Next];
                Image img = new Image();
                img.Source = S.Bmps[S.Var]; img.Width = S.BW; img.Height = S.BH; img.Stretch = Stretch.Fill;
                img.RenderTransformOrigin = new Point(0.5, 0.5);
                TransformGroup tg = new TransformGroup();
                tg.Children.Add(new ScaleTransform(S.Flip ? -1 : 1, 1));
                tg.Children.Add(new RotateTransform(S.Rot));
                img.RenderTransform = tg;
                Canvas.SetLeft(img, p.X - S.BW / 2); Canvas.SetTop(img, p.Y - S.BH / 2);
                S.OC.Children.Add(img);

                S.AI.Opacity = 0;
                SetWindowPos(S.AH, IntPtr.Zero, -30000, -30000, 0, 0, NOSIZE | NOACTIVATE);
                S.StartT = -1;
                S.NextAt = t + gap;
                S.Next++;
                if (S.Next >= S.Pos.Count) S.Done = true;
            }
            else
            {
                // il sort d'un point au centre de l'ecran, grossit et glisse jusqu'a sa place
                double em = 1 - Math.Pow(1 - pr, 3);                 // deplacement : ease-out
                double ez = EaseOutBack(pr);                         // taille : leger rebond a la fin
                double sc = 0.02 + 0.98 * ez;
                S.AS.ScaleX = (S.Flip ? -sc : sc); S.AS.ScaleY = sc;
                S.AR.Angle = S.Rot - 30 * (1 - em);
                S.AI.Opacity = Math.Min(1, pr * 6);
                double ccx = S.B.X + S.B.Width / 2.0, ccy = S.B.Y + S.B.Height / 2.0;
                int ax = (int)(ccx + (S.TX - ccx) * em - S.APW / 2.0);
                int ay = (int)(ccy + (S.TY - ccy) * em - S.APH / 2.0);
                SetWindowPos(S.AH, tmPaused ? BOTTOM : TOPMOST, ax, ay, 0, 0, NOSIZE | NOACTIVATE);
                if (!tmPaused)
                {
                    if (S.BanH != IntPtr.Zero) SetWindowPos(S.BanH, TOPMOST, 0, 0, 0, 0, NOMOVE | NOSIZE | NOACTIVATE);
                    if (S.XH != IntPtr.Zero) SetWindowPos(S.XH, TOPMOST, 0, 0, 0, 0, NOMOVE | NOSIZE | NOACTIVATE);
                }
            }
        }
    }
}
'@

$names = 'System','PresentationFramework','PresentationCore','WindowsBase','System.Xaml','System.Windows.Forms','System.Drawing'
$refs  = [AppDomain]::CurrentDomain.GetAssemblies() |
         Where-Object { $names -contains $_.GetName().Name } |
         ForEach-Object { $_.Location }

Add-Type -TypeDefinition $code -ReferencedAssemblies $refs -IgnoreWarnings

# Photo du croissant detouree (PNG en base64)
$Photo = ''

[Croissant]::Run($Cm, $Duration, $Gap, $Minutes, $Message, $Photo)
